// 辅助函数：根据 ID 获取名称
function getDepartmentName(id) {
    const dept = DEPARTMENTS.find(d => d.id === id);
    return dept ? dept.name : '-';
}

function getEmployeeTypeName(id) {
    const type = EMPLOYEE_TYPES.find(t => t.id === id);
    return type ? type.name : '-';
}

// v2.13.24 新增：考勤班次 Badge 渲染助手（用于 booking/index.html 列表）
function attendanceBadgeHtml(attendanceTypeId) {
    const type = ATTENDANCE_TYPES_FULL.find(t => t.id === attendanceTypeId);
    if (!type) return '<span class="badge bg-light text-dark">-</span>';
    const code = type.code || 'DEFAULT';
    const cls = ATTENDANCE_BADGE[code] || 'bg-secondary';
    return `<span class="badge ${cls}">${type.name}</span>`;
}

function getEmploymentStatusName(id) {
    const status = EMPLOYMENT_STATUSES.find(s => s.id === id);
    return status ? status.name : '-';
}

function getAttendanceTypeName(id) {
    const type = ATTENDANCE_TYPES.find(t => t.id === id);
    return type ? type.name : '-';
}

// 辅助函数：根据名称获取 ID（用于表单提交）
function getDepartmentId(name) {
    const dept = DEPARTMENTS.find(d => d.name === name);
    return dept ? dept.id : null;
}

function getEmployeeTypeId(codeOrName) {
    // 支持 code 或 name
    let type = EMPLOYEE_TYPES.find(t => t.code === codeOrName);
    if (!type) type = EMPLOYEE_TYPES.find(t => t.name === codeOrName);
    return type ? type.id : null;
}

function getEmploymentStatusId(statusValue) {
    // 在职状态使用 1/2/3 直接作为ID
    return statusValue;
}

function getAttendanceTypeId(code) {
    const type = ATTENDANCE_TYPES.find(t => t.code === code);
    return type ? type.id : null;
}

// ID → 名称 快捷映射（用于列表渲染）
const DEPT_BY_ID = DEPARTMENTS.reduce((acc, d) => { acc[d.id] = d.name; return acc; }, {});
const EMP_TYPE_BY_ID = EMPLOYEE_TYPES.reduce((acc, t) => { acc[t.id] = t.name; return acc; }, {});
const EMP_STATUS_BY_ID = EMPLOYMENT_STATUSES.reduce((acc, s) => { acc[s.id] = s.name; return acc; }, {});
const ATTENDANCE_BY_ID = ATTENDANCE_TYPES.reduce((acc, t) => { acc[t.id] = t.name; return acc; }, {});

