// ---------------------------------------------------------------------
// 严格唯一 active 匹配算法（v2.11.2 — 修复"4 个菜单同时 active"BUG）
//
// 核心原则：
//   1. 先清除所有 .menu-item / .nav-link 的 active 类
//   2. 按当前 URL pathname 自动精确匹配：最长前缀匹配
//   3. 兜底匹配首页（没有任何匹配时）
//   4. 保证同时只有 0 个或 1 个菜单处于 active 状态
//
// 关键修复点（相对 v2.11.0）：
//   - 用 startsWith(href + '/') 替代 startsWith(href)，避免根路径 '/' 过度匹配
//   - 最长前缀匹配，确保 /Personnel/Edit 匹配 /Personnel 而非 /
//   - 删除传入参数 active=xxx 的方式（容易遗漏/出错）
//   - 删除所有 HTML 硬编码的 active 类（避免重复）
//
// 兼容：
//   - 原型菜单 href="../xxx.html"（相对路径）→ 自动归一化为 "/xxx.html"
//   - Razor 菜单 href="/Personnel"（绝对路径）→ 保持原样
// ---------------------------------------------------------------------
function __ensureSingleActive() {
    if (typeof window === 'undefined' || !document) return;
    var currentPath = (window.location.pathname || '/').replace(/\/$/, '') || '/';
    // 1) 收集所有菜单链接（菜单项 + 旧式 nav-link）
    var links = Array.prototype.slice.call(
        document.querySelectorAll('.menu-item, .nav-link')
    );
    if (links.length === 0) return;
    // 2) 先清除所有 active 类（关键：先清后选）
    links.forEach(function (link) {
        link.classList.remove('active');
    });
    // 3) 归一化 href：去除相对前缀 "../" 用于比较
    function normHref(href) {
        if (!href) return '';
        // 原型 "../xxx.html" → "/xxx.html"；Razor "/Personnel" → "/Personnel"
        return href.replace(/^(\.\.\/)+/, '/');
    }
    // 4) 精确匹配：优先完全相等，其次最长前缀（href + '/' 必须出现）
    var bestMatch = null;
    var bestLen = 0;
    links.forEach(function (link) {
        var href = link.getAttribute('href') || link.getAttribute('data-href') || '';
        var nHref = normHref(href);
        if (!nHref) return;
        // 匹配规则：当前路径 === href 或 当前路径以 "href + '/'" 开头
        // 注意：根 '/' 单独处理，避免匹配所有路径
        var matched = (currentPath === nHref)
            || (nHref !== '/' && currentPath.indexOf(nHref + '/') === 0);
        if (matched && nHref.length > bestLen) {
            bestLen = nHref.length;
            bestMatch = link;
        }
    });
    // 5) 添加唯一 active（兜底首页）
    if (bestMatch) {
        bestMatch.classList.add('active');
    } else {
        // 兜底：匹配 href 包含 "index.html" 或 href === "/"
        var homeLink = document.querySelector('.menu-item[href*="index.html"]')
                    || document.querySelector('.menu-item[href="/"]')
                    || document.querySelector('.menu-item[data-href="/"]');
        if (homeLink) homeLink.classList.add('active');
    }
}
// 暴露到 window（供内联 <script> 和外部调用）
if (typeof window !== 'undefined') {
    window.__ensureSingleActive = __ensureSingleActive;
}
function statusBadge(s) {
    return `<span class="badge ${STATUS_BADGE[s]}">${STATUS_MAP[s]}</span>`;
}
function formatDate(d) {
    return d ? d.substring(0, 10) : '-';
}
