const RESIDENCY_STATUS = { 1: "在宿", 2: "已退宿", 3: "调宿中" };
const RESIDENCY_BADGE = { 1: "bg-success", 2: "bg-secondary", 3: "bg-warning text-dark" };
// 辅助：根据员工ID查找员工（v2.11.7 增强 - 支持多种查找方式）
function findEmployee(idOrCode) {
    if (idOrCode === null || idOrCode === undefined) return null;
    // 数字 ID
    if (typeof idOrCode === 'number') {
        return PERSONNEL.find(p => p.id === idOrCode)
            || PERSONNEL.find(p => String(p.employeeCode) === String(idOrCode));
    }
    // 字符串 employeeCode（如 "EMP-2026-228"）
    const str = String(idOrCode);
    return PERSONNEL.find(p => p.employeeCode === str)
        || PERSONNEL.find(p => String(p.id) === str);
}
function findDorm(code) { return DORMS.find(d => d.dormCode === code); }
// v2.11.2 增补 d：住宿状态派生字段（基于 BOOKINGS 最后一条记录推断）
// LIVING 在宿 | LEFT 已退宿 | BOOKED 预订中 | CANCELLED 已取消 | NONE 无记录
function getLivingStatus(employeeId) {
    const records = BOOKINGS
        .filter(b => b.employeeId === employeeId)
        .sort((a, b) => b.bookingDate.localeCompare(a.bookingDate));
    if (records.length === 0) return 'NONE';
    const last = records[0];
    if (last.status === 4) return 'CANCELLED';
    if (last.status === 1) return 'BOOKED';
    if (last.status === 3) return 'LEFT';
    if (last.status === 2 && last.type === 1) return 'LIVING';
    return 'NONE';
}
const LIVING_STATUS_NAME  = { LIVING: '在宿', LEFT: '已退宿', BOOKED: '预订中', CANCELLED: '已取消', NONE: '无记录' };
const LIVING_STATUS_BADGE = { LIVING: 'bg-success', LEFT: 'bg-secondary', BOOKED: 'bg-info text-dark', CANCELLED: 'bg-warning text-dark', NONE: 'bg-light text-dark' };
function livingBadge(s) {
    return `<span class="badge ${LIVING_STATUS_BADGE[s] || 'bg-light text-dark'}">${LIVING_STATUS_NAME[s] || s}</span>`;
}
// 辅助：获取宿舍当前在住人数
function currentResidents(dormCode) {
    return RESIDENCIES.filter(r => r.dormCode === dormCode && r.status === 1).length;
}
// 辅助：v2.13.95 宿舍档案列表「班次」列派生
// 返回该宿舍房号当前在宿员工（Status=1）的考勤班次去重集合（按 AttendanceType.Id 升序）
// 数据关系：RESIDENCIES → PERSONNEL (EmployeeId=PERSONNEL.Id) → ATTENDANCE_TYPES_FULL (PERSONNEL.attendanceTypeId=ATTENDANCE_TYPES_FULL.id)
// 注意：mock-data.js 中员工表名为 PERSONNEL（不是 EMPLOYEES）；考勤班次表名为 ATTENDANCE_TYPES_FULL（不是 ATTENDANCE_TYPES，ATTENDANCE_TYPES 是字典）
function currentAttendanceTypes(dormCode) {
    const staying = RESIDENCIES.filter(r => r.dormCode === dormCode && r.status === 1);
    const typeIds = staying
        .map(r => PERSONNEL.find(e => e.id === r.employeeId))
        .filter(e => e && e.attendanceTypeId)
        .map(e => e.attendanceTypeId);
    if (typeIds.length === 0) return [];
    const uniqueIds = [...new Set(typeIds)].sort((a, b) => a - b);
    return uniqueIds
        .map(id => ATTENDANCE_TYPES_FULL.find(t => t.id === id))
        .filter(t => t)
        .map(t => t.name);
}
// 辅助：v2.13.107 宿舍档案列表「班组」列派生
// 返回该宿舍房号当前在宿员工（Status=1）的所属班组去重集合（按 Team.SortOrder 升序）
// 数据关系：RESIDENCIES → PERSONNEL (EmployeeId=PERSONNEL.Id) → TEAMS (PERSONNEL.teamId=TEAMS.id)
// 示例：A101 入住 3 人（A班/B班/B班）→ 返回 [{name:'一班', code:'TEAM_A1'}, {name:'三班', code:'TEAM_B1'}]（去重 + 按 SortOrder 排序）
function currentTeams(dormCode) {
    const staying = RESIDENCIES.filter(r => r.dormCode === dormCode && r.status === 1);
    const teams = staying
        .map(r => PERSONNEL.find(e => e.id === r.employeeId))
        .filter(e => e && e.teamId)
        .map(e => TEAMS.find(t => t.id === e.teamId))
        .filter(t => t); // 过滤掉 TEAMS 中不存在的孤儿 teamId
    if (teams.length === 0) return [];
    // 按 SortOrder 升序 + 去重（同 teamId 仅保留第一个）
    const seen = new Set();
    return teams
        .slice()
        .sort((a, b) => (a.sortOrder || 0) - (b.sortOrder || 0))
        .filter(t => { if (seen.has(t.id)) return false; seen.add(t.id); return true; });
}
// 辅助：获取宿舍的所有住宿记录（按入住日期倒序）
function dormHistory(dormCode) {
    return RESIDENCIES.filter(r => r.dormCode === dormCode)
                       .sort((a, b) => b.checkInDate.localeCompare(a.checkInDate));
}
// 辅助：获取员工的所有住宿记录
function employeeHistory(employeeId) {
    return RESIDENCIES.filter(r => r.employeeId === employeeId)
                       .sort((a, b) => b.checkInDate.localeCompare(a.checkInDate));
}
// 辅助：获取员工当前在宿记录
function activeResidency(employeeId) {
    return RESIDENCIES.find(r => r.employeeId === employeeId && r.status === 1);
}
