// v2.11.4：3状态系统（0=未完成/占位记录 1=正常 2=已修正），删除"已作废"和单独的"未抄表"状态
const METER_STATUS = { 0: "未完成", 1: "正常", 2: "已修正" };
const METER_STATUS_BADGE = { 0: "bg-light text-dark border", 1: "bg-success", 2: "bg-warning text-dark" };
const METER_TYPES = [
    { key: "cold", name: "冷水表", unit: "m³", icon: "bi-droplet", color: "text-primary" },
    { key: "hot", name: "热水表", unit: "m³", icon: "bi-fire", color: "text-danger" },
    { key: "electric", name: "电表", unit: "度", icon: "bi-lightning-charge", color: "text-warning" }
];
// 抄表员字典（PDA 操作员）
const METER_OPERATORS = ["陈师傅", "刘师傅"];
// 辅助：抄表月份倒序去重列表
function meterMonths() {
    return [...new Set(METER_RECORDS.map(m => m.readMonth))].sort((a, b) => b.localeCompare(a));
}
// 辅助：某宿舍在指定月份之前最近一条有效读数（用于计算用量、校验递增）
// v2.11.4：排除 status=0(未抄表)，仅取有效记录
function prevMeter(dormCode, readMonth) {
    return METER_RECORDS
        .filter(m => m.dormCode === dormCode && m.readMonth < readMonth && (m.status === 1 || m.status === 2))
        .sort((a, b) => b.readMonth.localeCompare(a.readMonth))[0] || null;
}
// 辅助：计算某条抄表记录的三表用量（v2.11.4：status=0 时缺失表项用量强制 0，永不负数）
function meterUsage(m) {
    const prev = prevMeter(m.dormCode, m.readMonth);
    if (!prev) return { prev: null, cold: null, hot: null, electric: null };
    // v2.11.4：status=0（未完成）时，缺失表项（读数=0）用量强制为 0
    // 所有用量统一使用 max(0, 本月-上月)，永不出现负数
    const coldUsage = m.status === 0 && m.coldMeter === 0 ? 0
        : Math.max(0, +(m.coldMeter - prev.coldMeter).toFixed(2));
    const hotUsage = m.status === 0 && m.hotMeter === 0 ? 0
        : Math.max(0, +(m.hotMeter - prev.hotMeter).toFixed(2));
    const electricUsage = m.status === 0 && m.electricMeter === 0 ? 0
        : Math.max(0, +(m.electricMeter - prev.electricMeter).toFixed(2));
    return {
        prev,
        cold: coldUsage,
        hot: hotUsage,
        electric: electricUsage
    };
}
// 辅助：根据 id 查抄表记录
function findMeter(id) { return METER_RECORDS.find(m => m.id === id); }
// 辅助：本月抄表进度统计（v2.11.4：3状态系统，0=未完成/占位记录）
function meterCoverage(readMonth) {
    const active = DORMS.filter(d => d.isActive);
    // 已抄：状态=1 正常 或 2 已修正
    const read = new Set(METER_RECORDS.filter(m => m.readMonth === readMonth && (m.status === 1 || m.status === 2)).map(m => m.dormCode));
    // 未完成/占位：状态=0（三表全0或部分为0）
    const unfinished = new Set(METER_RECORDS.filter(m => m.readMonth === readMonth && m.status === 0).map(m => m.dormCode));
    // 真正未覆盖：没有任何记录的宿舍
    const allCovered = new Set([...read, ...unfinished]);
    const uncovered = active.filter(d => !allCovered.has(d.dormCode)).map(d => d.dormCode);
    return {
        total: active.length,
        read: read.size,
        unfinished: unfinished.size,
        uncovered: uncovered.length,
        uncoveredList: uncovered,
        // 完整列表（用于详细展示）
        details: {
            read: [...read],
            unfinished: [...unfinished],
            uncovered: [...uncovered]
        }
    };
}
// 辅助：v2.11.4 — 自动补全占位记录（每月每启用宿舍必须有 1 条，status=0 为默认值）
(function fillUnreadMeterRecords() {
    const months = ['2026-06', '2026-07'];
    const existing = new Set(METER_RECORDS.map(m => `${m.dormCode}|${m.readMonth}`));
    const nextId = METER_RECORDS.reduce((mx, m) => Math.max(mx, m.id), 0) + 1;
    let idCounter = nextId;
    DORMS.filter(d => d.isActive).forEach(d => {
        months.forEach(month => {
            const key = `${d.dormCode}|${month}`;
            if (!existing.has(key)) {
                METER_RECORDS.push({
                    id: idCounter++,
                    dormCode: d.dormCode,
                    dormAddress: d.address,
                    readMonth: month,
                    coldMeter: 0,
                    hotMeter: 0,
                    electricMeter: 0,
                    operator: '',
                    deviceSn: '',
                    status: 0,  // v2.11.4：未完成/占位记录（默认值）
                    remark: '[2026-07-01 00:00 自动生成占位记录]',
                    createdAt: ''
                });
            }
        });
    });
    // v2.11.4 演示：把 2026-07 月的 10 间宿舍改为"未完成"状态（演示占位记录）
    const unreadSampleCodes = ['D-014', 'D-062', 'D-126', 'D-167', 'D-185', 'D-200', 'D-166', 'D-169', 'D-172', 'D-176'];
    unreadSampleCodes.forEach(code => {
        const recs = METER_RECORDS.filter(m => m.readMonth === '2026-07' && m.dormCode === code);
        // 删除现有的"正常/已修正"记录
        recs.filter(r => r.status === 1 || r.status === 2).forEach(r => {
            const idx = METER_RECORDS.indexOf(r);
            if (idx >= 0) METER_RECORDS.splice(idx, 1);
        });
        // 添加"未完成"占位记录（三表全0）
        const dorm = DORMS.find(d => d.dormCode === code);
        if (dorm && dorm.isActive) {
            METER_RECORDS.push({
                id: idCounter++,
                dormCode: code,
                dormAddress: dorm.address,
                readMonth: '2026-07',
                coldMeter: 0,
                hotMeter: 0,
                electricMeter: 0,
                operator: '系统自动生成',
                deviceSn: 'AUTO',
                status: 0,  // v2.11.4：未完成（统一用0）
                remark: '[2026-07-01 00:00 自动生成占位记录]',
                createdAt: ''
            });
        }
    });
    // v2.11.4 演示：把 2026-07 月的 5 间宿舍改为"未完成"状态（部分表项缺失）
    const unfinishedSampleCodes = ['D-005', 'D-015', 'D-030', 'D-045', 'D-060'];
    unfinishedSampleCodes.forEach(code => {
        const recs = METER_RECORDS.filter(m => m.readMonth === '2026-07' && m.dormCode === code && (m.status === 1 || m.status === 2));
        recs.forEach(r => {
            // 把其中一个表项清零（如热水表和电表）
            r.hotMeter = 0;
            r.electricMeter = 0;
            r.status = 0;  // v2.11.4：未完成（统一用0）
            r.remark = '演示：热水表与电表数据未上传（部分缺失）';
        });
    });
    // v2.11.4 演示：3 条记录带"覆盖历史"备注（模拟之前导入覆盖后保留旧数据）
    const historySampleCodes = ['D-010', 'D-025', 'D-040'];
    historySampleCodes.forEach(code => {
        const rec = METER_RECORDS.find(m => m.readMonth === '2026-07' && m.dormCode === code && m.status === 1);
        if (rec) {
            rec.remark = (rec.remark || '') +
                '\n[2026-07-08 14:25 覆盖前数据] cold=88.50, hot=22.30, electric=120.00, status=1, operator=陈师傅' +
                '\n[2026-07-08 16:40 覆盖前数据] cold=89.20, hot=23.10, electric=125.00, status=1, operator=刘师傅';
        }
    });
})();
// =====================================================================
// 通用分页组件（默认每页 10 条，可调整并持久化到 localStorage；
// 仅当总条数 > 10 时显示分页条）
// 用法：
//   const list = registerList({ key, footId, getData, renderRows(items,total), totalId? });
//   list.draw();               // 渲染当前页
//   list.reset();              // 筛选变化后回到第 1 页并渲染
// =====================================================================
const PAGE_SIZE_OPTIONS = [10, 20, 50, 100];
const PAGE_SIZE_KEY = 'proto.pageSize';
function getPageSize() {
    const v = parseInt(localStorage.getItem(PAGE_SIZE_KEY), 10);
    return PAGE_SIZE_OPTIONS.includes(v) ? v : 10;
}
const __LISTS = {};
function registerList(opts) {
    const inst = Object.assign({ page: 1 }, opts);
    inst.draw = () => __drawList(opts.key);
    inst.reset = () => { inst.page = 1; __drawList(opts.key); };
    __LISTS[opts.key] = inst;
    return inst;
}
function __drawList(key) {
    const inst = __LISTS[key];
    const data = inst.getData();
    const size = getPageSize();
    const total = data.length;
    const totalPages = Math.max(1, Math.ceil(total / size));
    if (inst.page > totalPages) inst.page = totalPages;
    if (inst.page < 1) inst.page = 1;
    const start = (inst.page - 1) * size;
    const items = data.slice(start, start + size);
    if (inst.totalId) { const el = document.getElementById(inst.totalId); if (el) el.textContent = total; }
    inst.renderRows(items, total, start);
    __drawPager(key, total, totalPages, size, start, items.length);
}
function __drawPager(key, total, totalPages, size, start, shown) {
    const inst = __LISTS[key];
    const foot = document.getElementById(inst.footId);
    if (!foot) return;
    if (total <= 10) { foot.innerHTML = ''; foot.style.display = 'none'; return; }
    foot.style.display = '';
    const page = inst.page;
    const from = start + 1, to = start + shown;
    const cell = (label, p, disabled, active) =>
        `<li class="page-item ${disabled ? 'disabled' : ''} ${active ? 'active' : ''}">`
        + `<a class="page-link" href="#" onclick="event.preventDefault();${disabled || active ? '' : `__listGo('${key}',${p})`}">${label}</a></li>`;
    let nums = '';
    for (let p = 1; p <= totalPages; p++) {
        if (p === 1 || p === totalPages || (p >= page - 2 && p <= page + 2)) nums += cell(p, p, false, p === page);
        else if (p === page - 3 || p === page + 3) nums += '<li class="page-item disabled"><span class="page-link">…</span></li>';
    }
    foot.innerHTML =
        '<div class="d-flex justify-content-between align-items-center flex-wrap gap-3">'
        + '<div></div>'
        + '<div class="flex-grow-1 d-flex justify-content-center"><nav><ul class="pagination pagination-sm mb-0">'
        + cell('«', page - 1, page === 1, false) + nums + cell('»', page + 1, page === totalPages, false)
        + '</ul></nav></div>'
        + '<div class="d-flex align-items-center gap-3">'
        + '<span class="text-muted small">每页</span>'
        + '<select class="form-select form-select-sm" style="width:auto" onchange="__listSize(this.value)">'
        + PAGE_SIZE_OPTIONS.map(o => `<option value="${o}" ${o === size ? 'selected' : ''}>${o}</option>`).join('')
        + '</select><span class="text-muted small">条</span>'
        + `<span class="text-muted small"> | &nbsp;&nbsp;共 <strong>${total}</strong> 条 · 第 ${from}-${to} 条 · 共 ${totalPages} 页&nbsp;&nbsp;</span>`
        + '</div>'
        + '</div>';
}
function __listGo(key, p) { __LISTS[key].page = p; __drawList(key); }
function __listSize(v) {
    localStorage.setItem(PAGE_SIZE_KEY, String(parseInt(v, 10)));
    Object.values(__LISTS).forEach(l => { l.page = 1; __drawList(l.key); });
}
