// v2.11.24 数据规范化 IIFE（取代 v2.11.23 部门映射规则）
// 规范文档：00-方案文档/43-无效FK归一通用规范-v2.11.24.md
// 审计脚本：00-方案文档/04-HTML原型/_audit_v2_11_24.js
// 关联 C#： DormManage.Shared/Services/DictionaryFallbackService.cs
// =====================================================================
// 规则摘要：
//   - 所有不在字典范围内的 FK 值 → 归一为该字典最后一项的 ID
//   - 通用工具函数：getLastDictId(dictName) / normalizeFK(items, fkField, dictName, nameField)
//   - 首期应用：employeeTypeId（其余 FK 工具已就绪，按需启用）
//
// 历史兼容：
//   v2.11.7 引入本 IIFE，v2.11.7.CORRECT 规范 5 种员工类型但未归一 197 条无效 ID 6/7/8
//   v2.11.23 §2.2 规则 2b 采用部门语义映射（DEPRECATED）
//   v2.11.24 统一归一为字典最后一项 ID（当前末项 = 5 / 驻场）
// =====================================================================
(function normalizeData() {
    'use strict';

    if (typeof PERSONNEL === 'undefined') return;

    // =====================================================================
    // v2.11.24 通用规范函数：无效 FK 值归一规则
    // 规则：所有不在字典范围内的 FK 值 → 更新为基础资料字典最后一个选项的 ID
    // 应用范围：employeeTypeId, attendanceTypeId, departmentId, employmentStatusId, residenceStatusId 等
    // =====================================================================
    function getLastDictId(dictName) {
        if (typeof window !== 'undefined' && typeof window[dictName] !== 'undefined') {
            var d = window[dictName];
            if (Array.isArray(d) && d.length > 0) return d[d.length - 1].id;
        }
        // 全局变量查找
        if (typeof globalThis !== 'undefined' && typeof globalThis[dictName] !== 'undefined') {
            var d2 = globalThis[dictName];
            if (Array.isArray(d2) && d2.length > 0) return d2[d2.length - 1].id;
        }
        return null;
    }

    function normalizeFK(items, fkField, dictName, nameField) {
        if (typeof items === 'undefined' || !Array.isArray(items)) return 0;
        var lastId = getLastDictId(dictName);
        if (lastId === null) return 0;
        // 找到字典对象以获取 Name
        var dict = (typeof globalThis !== 'undefined' && typeof globalThis[dictName] !== 'undefined')
            ? globalThis[dictName]
            : null;
        var lastName = '';
        if (dict && Array.isArray(dict)) {
            var lastObj = dict.find(function (x) { return x.id === lastId; });
            if (lastObj) lastName = lastObj.name || '';
        }
        var validIds = [];
        if (dict && Array.isArray(dict)) {
            for (var i = 0; i < dict.length; i++) validIds.push(dict[i].id);
        }
        var fixed = 0;
        items.forEach(function (it) {
            var v = it[fkField];
            if (v === undefined || v === null) {
                // v2.11.24 规则：缺失 FK 也归一为字典最后一项
                it[fkField] = lastId;
                if (nameField) it[nameField] = lastName;
                fixed++;
            } else if (validIds.indexOf(v) === -1) {
                // v2.11.24 规则：无效 FK（不在字典范围内）→ 字典最后一项
                it[fkField] = lastId;
                if (nameField) it[nameField] = lastName;
                fixed++;
            }
        });
        return fixed;
    }

    // 1. PERSONNEL 考勤班次规范化（旧 → 新）
    let attendanceFixed = 0;
    PERSONNEL.forEach(p => {
        if ((p.attendanceTypeId === undefined || p.attendanceTypeId === null) && p.attendanceType) {
            const t = (typeof ATTENDANCE_TYPES !== 'undefined')
                ? ATTENDANCE_TYPES.find(x => x.code === p.attendanceType)
                : null;
            if (t) {
                p.attendanceTypeId = t.id;
                p.attendanceTypeName = t.name;
                attendanceFixed++;
            }
        }
    });

    // 2. PERSONNEL 员工类型规范化（旧 → 新）
    let employeeTypeFixed = 0;
    PERSONNEL.forEach(p => {
        if ((p.employeeTypeId === undefined || p.employeeTypeId === null) && p.employeeType) {
            const t = (typeof EMPLOYEE_TYPES !== 'undefined')
                ? EMPLOYEE_TYPES.find(x => x.code === p.employeeType || x.name === p.employeeType)
                : null;
            if (t) {
                p.employeeTypeId = t.id;
                p.employeeTypeName = t.name;
                employeeTypeFixed++;
            }
        }
    });

    // 2b. PERSONNEL 员工类型 FK 值校正（v2.11.7.CORRECT → v2.11.24 统一规则）
    // 基础资料-员工类型表仅定义 5 种（ID 1-5），纠正 mock-data 中误设的 ID 6-10
    // v2.11.24 规则：所有无效 FK 值统一更新为基础资料字典最后一个选项的 ID 主键
    //   即 employeeTypeId ∈ {6,7,8,9,10,...} → employeeTypeId = 5（驻场，最后一个有效 ID）
    let employeeTypeCorrected = 0;
    // 取基础资料 EMPLOYEE_TYPES 字典的最后一个 ID（动态获取，避免硬编码）
    var lastEmployeeTypeId = (typeof EMPLOYEE_TYPES !== 'undefined' && EMPLOYEE_TYPES.length > 0)
        ? EMPLOYEE_TYPES[EMPLOYEE_TYPES.length - 1].id
        : 5; // fallback 默认 5
    PERSONNEL.forEach(p => {
        if (p.employeeTypeId != null && p.employeeTypeId > EMPLOYEE_TYPES.length) {
            // v2.11.24 统一规则：无效 ID → 字典最后一个 ID
            p.employeeTypeId = lastEmployeeTypeId;
            // 同步修正 employeeTypeName
            if (typeof EMPLOYEE_TYPES !== 'undefined') {
                var ct = EMPLOYEE_TYPES.find(function(x) { return x.id === lastEmployeeTypeId; });
                if (ct) p.employeeTypeName = ct.name;
            }
            employeeTypeCorrected++;
        }
    });

    // 3. PERSONNEL 部门规范化（旧 → 新）
    let departmentFixed = 0;
    PERSONNEL.forEach(p => {
        if ((p.departmentId === undefined || p.departmentId === null) && p.department) {
            const d = (typeof DEPARTMENTS !== 'undefined')
                ? DEPARTMENTS.find(x => x.name === p.department || x.code === p.department)
                : null;
            if (d) p.departmentId = d.id;
            departmentFixed++;
        }
    });

    // 4. PERSONNEL 在职状态规范化（旧 → 新）
    let statusFixed = 0;
    PERSONNEL.forEach(p => {
        if ((p.employmentStatusId === undefined || p.employmentStatusId === null) && p.status) {
            p.employmentStatusId = p.status;
            const s = (typeof EMPLOYMENT_STATUSES !== 'undefined')
                ? EMPLOYMENT_STATUSES.find(x => x.id === p.status)
                : null;
            if (s) p.employmentStatusName = s.name;
            statusFixed++;
        }
    });

    // 5. EMPLOYEE_BILLS 规范化：移除冗余缓存字段 + employeeId 转换
    let billsFixed = 0;
    if (typeof EMPLOYEE_BILLS_202607 !== 'undefined') {
        EMPLOYEE_BILLS_202607.forEach(b => {
            // 删除 v2.11.7 §2.4.1 文档明确禁止的冗余缓存字段
            delete b.attendanceType;
            // v2.11.22 修复：保留 employeeType 但通过 PERSONNEL 关联重新填充（避免 undefined）
            // employeeId 字符串 → 数字（兼容 employeeCode 形式的引用）
            if (typeof b.employeeId === 'string' && isNaN(parseInt(b.employeeId))) {
                const p = PERSONNEL.find(p => p.employeeCode === b.employeeId);
                if (p) {
                    b.employeeId = p.id;
                    billsFixed++;
                }
            }
            // v2.11.22 修复：通过 employeeId 关联 PERSONNEL 重新填充 employeeType/attendanceType 等字段
            if (b.employeeId) {
                const p = PERSONNEL.find(emp => emp.id === b.employeeId);
                if (p) {
                    // 关联 employeeType：优先 FK + Name，回退字符串
                    if (!b.employeeType) {
                        if (p.employeeTypeName) {
                            b.employeeType = p.employeeTypeName;
                        } else if (p.employeeType) {
                            b.employeeType = p.employeeType;
                        } else if (typeof EMPLOYEE_TYPES !== 'undefined') {
                            const t = EMPLOYEE_TYPES.find(t => t.id === p.employeeTypeId);
                            if (t) b.employeeType = t.name;
                        }
                    }
                    // 关联 attendanceType（v2.11.7 §2.4.1 删除后重建）
                    if (!b.attendanceType && (p.attendanceTypeName || p.attendanceType)) {
                        b.attendanceType = p.attendanceTypeName || p.attendanceType;
                    }
                }
            }
        });
    }

    // 6. DORM_BILLS 规范化：移除冗余缓存字段
    if (typeof DORM_BILLS_202607 !== 'undefined') {
        DORM_BILLS_202607.forEach(b => {
            // residentCount 保留（DormBilling 表字段名）
            // 不删除任何字段
        });
    }

    // 控制台提示（便于调试）
    if (typeof console !== 'undefined' && console.log) {
        console.log('[v2.11.7.CORRECT] mock-data.js 数据规范化完成：');
        console.log('  考勤班次补全：' + attendanceFixed + ' 条');
        console.log('  员工类型补全：' + employeeTypeFixed + ' 条');
        console.log('  员工类型校正：' + employeeTypeCorrected + ' 条（ID>5 映射回有效范围）');
        console.log('  部门补全：    ' + departmentFixed + ' 条');
        console.log('  在职状态补全：' + statusFixed + ' 条');
        console.log('  EMPLOYEE_BILLS employeeId 转换：' + billsFixed + ' 条');
    }

    // =====================================================================
    // v2.11.18 新增步骤：同步 PERSONNEL.dormCode 与 BOOKINGS 最后有效记录
    // =====================================================================
    // 修复 BUG：原 PERSONNEL.dormCode 与 BOOKINGS 不同步，导致：
    //   - 首页 KPI 1 入住人数（用 PERSONNEL.dormCode 非空计数）= 571
    //   - 人员清单 dormCode 列（用 getLatestDormCode 计算）= 548
    //   - 差异 24 条（已退房/已取消/仅预约但 PERSONNEL.dormCode 仍非空）
    //
    // 修复策略：
    //   以 BOOKINGS 最后有效记录为准，重新计算 PERSONNEL.dormCode：
    //   - 最后一条 BOOKINGS (type=1, status=2 在宿) → PERSONNEL.dormCode = 该记录 dormCode
    //   - 最后一条 BOOKINGS (type=2, status=3 已退房) → PERSONNEL.dormCode = null
    //   - 最后一条 BOOKINGS (status=1 预约) → PERSONNEL.dormCode = null（未生效）
    //   - 最后一条 BOOKINGS (status=4 已取消) → PERSONNEL.dormCode = null
    //   - 无任何 BOOKINGS 记录 → 保留 PERSONNEL.dormCode 原值（孤儿数据）
    // =====================================================================
    if (typeof BOOKINGS !== 'undefined' && typeof getLatestValidBooking === 'function') {
        let dormSynced = 0;
        let dormCleared = 0;
        PERSONNEL.forEach(p => {
            const last = getLatestValidBooking(p.id);
            if (!last) return; // 无 BOOKINGS 记录，保留原值
            const oldDorm = p.dormCode;
            let newDorm = oldDorm;
            if (last.type === 1 && last.status === 2) {
                // 在宿记录 → dormCode = 该记录 dormCode
                newDorm = last.dormCode || null;
            } else if (last.type === 2 && last.status === 3) {
                // 已退房 → 清空 dormCode
                newDorm = null;
            } else if (last.status === 1) {
                // 仅预约未入住 → 清空 dormCode（未生效）
                newDorm = null;
            } else if (last.status === 4) {
                // 已取消 → 清空 dormCode
                newDorm = null;
            }
            if (newDorm !== oldDorm) {
                p.dormCode = newDorm;
                if (newDorm) dormSynced++;
                else dormCleared++;
            }
        });

        if (typeof console !== 'undefined' && console.log) {
            console.log('[v2.11.18 BUGFIX] PERSONNEL.dormCode 与 BOOKINGS 同步完成：');
            console.log('  dormCode 同步更新：' + dormSynced + ' 条');
            console.log('  dormCode 清空：    ' + dormCleared + ' 条');
            console.log('  同步后入住人数(PERSONNEL.dormCode 非空)='
                + PERSONNEL.filter(p => p.dormCode !== null && p.dormCode !== '' && String(p.dormCode).trim() !== '').length);
            console.log('  同步后异常人员(非在职但有房号)='
                + PERSONNEL.filter(p => {
                    const sid = p.employmentStatusId !== undefined ? p.employmentStatusId : p.status;
                    return sid !== 1 && p.dormCode !== null && p.dormCode !== '';
                }).length);
        }

        // ⚠️ v2.11.30 移除：原 IIFE 内的 residenceStatusId 同步块
        //   原因：RESIDENCE_STATUS 和 getResidenceStatusCode 都定义在 IIFE 之后
        //         导致 typeof 检查恒为 false，整个同步块被跳过
        //   修复：提取为独立块，放到 RESIDENCE_STATUS + getResidenceStatusCode 定义之后执行
    }
})();

// =====================================================================
// v2.11.25/v2.11.30 修复：住宿状态字典 + 同步辅助函数全部提前到 IIFE 之后
// 根因（v2.11.25）：
//   normalizeData IIFE 内使用 typeof RESIDENCE_STATUS
//   但 RESIDENCE_STATUS 原 const 在 IIFE 之后顶层 → TDZ 错误
// 根因（v2.11.30）：
//   即使 RESIDENCE_STATUS 提前到 IIFE 之后，getLatestValidBooking/getResidenceStatusCode 仍在 IIFE 之后
//   导致 IIFE 内 typeof getResidenceStatusCode === 'function' 恒为 false
//   "同步 PERSONNEL.residenceStatusId"整个代码块被跳过 → 全部记录 residenceStatusId 为 null
// 修复：将 RESIDENCE_STATUS + BOOKING_STATUS_DICT + getLatestValidBooking + getResidenceStatusCode
//       + getResidenceStatusByCode 全部提前到 IIFE 结束之后、任何引用它们的代码之前
// =====================================================================

var RESIDENCE_STATUS = [
    { id: 1, code: 'LODGED',     name: '已住宿', color: 'bg-primary',         remark: 'BOOKINGS 入住登记生效中' },
    { id: 2, code: 'NOT_LODGED', name: '未住宿', color: 'bg-light text-dark', remark: '无记录/退房后/已取消' },
    { id: 3, code: 'PENDING',    name: '待入住', color: 'bg-warning text-dark', remark: 'BOOKINGS 预约未入住' }
];

const BOOKING_STATUS_DICT = [
    { id: 1, code: 'RESERVED',   name: '预约',   color: 'bg-warning text-dark', remark: '已预约未实际入住' },
    { id: 2, code: 'STAYING',    name: '在宿',   color: 'bg-success',           remark: '入住登记生效中' },
    { id: 3, code: 'CHECKED_OUT',name: '已退房', color: 'bg-secondary',         remark: '退房办理完成' },
    { id: 4, code: 'CANCELLED',  name: '已取消', color: 'bg-danger',            remark: '预约已取消' }
];

// 获取某员工的最后一次有效 BOOKING 记录（v2.11.30 提前）
// 有效记录：type=1 入住或 type=2 退房，且 status !== 4（未取消）
// 按 registrationDate 倒序，取最近一条
function getLatestValidBooking(empId) {
    if (typeof BOOKINGS === 'undefined') return null;
    var candidates = [];
    for (var i = 0; i < BOOKINGS.length; i++) {
        var b = BOOKINGS[i];
        if (b.employeeId !== empId) continue;
        if (b.status === 4) continue;
        if (b.type !== 1 && b.type !== 2) continue;
        candidates.push(b);
    }
    if (candidates.length === 0) return null;
    candidates.sort(function(a, b) {
        var da = a.registrationDate || a.bookingDate || '';
        var db = b.registrationDate || b.bookingDate || '';
        return db.localeCompare(da);
    });
    return candidates[0];
}

// 根据 BOOKINGS 最后有效记录推导住宿状态 code（v2.11.30 提前）
// 输入：p（PERSONNEL 对象）
// 输出：'LODGED' | 'NOT_LODGED' | 'PENDING'（基础资料 ResidenceStatus.code）
// 单一数据源原则：所有住宿状态取值都必须通过此函数获取
function getResidenceStatusCode(p) {
    if (!p) return 'NOT_LODGED';
    var b = (typeof getLatestValidBooking === 'function') ? getLatestValidBooking(p.id) : null;
    if (!b) return 'NOT_LODGED';
    if (b.type === 1 && b.status === 2) return 'LODGED';
    if (b.type === 1 && b.status === 1) return 'PENDING';
    if (b.type === 2 && b.status === 3) return 'NOT_LODGED';
    return 'NOT_LODGED';
}

// 根据 Code 获取住宿状态对象（基础资料字典查询函数）
function getResidenceStatusByCode(code) {
    if (!code) return null;
    for (var i = 0; i < RESIDENCE_STATUS.length; i++) {
        if (RESIDENCE_STATUS[i].code === code) return RESIDENCE_STATUS[i];
    }
    return null;
}

// =====================================================================
// v2.11.30 独立同步块：同步 PERSONNEL.residenceStatusId 与 RESIDENCE_STATUS
// 关联路径：PERSONNEL → getResidenceStatusCode → RESIDENCE_STATUS
// 执行时机：所有依赖（RESIDENCE_STATUS/getResidenceStatusCode）定义完毕后立即执行
// 必须在 getResidenceStatusByCode 定义之后、所有引用 PERSONNEL.residenceStatusId 的代码之前
// =====================================================================
if (typeof getResidenceStatusCode === 'function' && typeof RESIDENCE_STATUS !== 'undefined') {
    let residenceSynced = 0;
    PERSONNEL.forEach(p => {
        const code = getResidenceStatusCode(p);
        const rs = RESIDENCE_STATUS.find(function (r) { return r.code === code; });
        if (rs) {
            const oldId = p.residenceStatusId;
            p.residenceStatusId = rs.id;
            p.residenceStatusCode = rs.code;
            p.residenceStatusName = rs.name;
            if (oldId !== rs.id) residenceSynced++;
        }
    });

    if (typeof console !== 'undefined' && console.log) {
        console.log('[v2.11.30 BUGFIX] PERSONNEL.residenceStatusId 与 ResidenceStatus 同步完成：');
        console.log('  住宿状态同步：' + residenceSynced + ' 条');
        console.log('  已住宿(LODGED)：'
            + PERSONNEL.filter(p => p.residenceStatusId === 1).length + ' 人');
        console.log('  未住宿(NOT_LODGED)：'
            + PERSONNEL.filter(p => p.residenceStatusId === 2).length + ' 人');
        console.log('  待入住(PENDING)：'
            + PERSONNEL.filter(p => p.residenceStatusId === 3).length + ' 人');
    }
}

