// 员工类型 Badge 颜色映射（v2.11.7.CORRECT：仅 5 种基础类型，与基础资料-员工类型列表一致）
if (typeof EMPLOYEE_TYPE_BADGE === 'undefined') {
    var EMPLOYEE_TYPE_BADGE = {
        'CONTRACT':   'bg-secondary',                          // 合同工-灰
        'TEMPORARY':  'bg-warning text-dark',                  // 临时工-橙
        'OUTSOURCE':  'bg-info text-dark',                     // 外包-青
        'INTERN':     'bg-success',                            // 实习生-绿
        'ONSITE':     'bg-dark',                               // 驻场-紫
        'OTHER':      'bg-light text-dark border'              // 其他-浅灰（兜底）
    };
}

// 员工类型 Badge 渲染助手（按人员对象 emp 取 Code 后映射）
function employeeTypeBadge(emp) {
    if (!emp) return '<span class="badge bg-light text-muted">-</span>';
    var code = null;
    if (emp.employeeTypeId != null) {
        var t = (typeof EMPLOYEE_TYPES !== 'undefined') ? EMPLOYEE_TYPES.find(function(x){return x.id === emp.employeeTypeId;}) : null;
        if (t) code = t.code;
    }
    if (!code && emp.employeeType) {
        // 直接匹配 code
        var t2 = (typeof EMPLOYEE_TYPES !== 'undefined') ? EMPLOYEE_TYPES.find(function(x){return x.code === emp.employeeType || x.name === emp.employeeType;}) : null;
        if (t2) code = t2.code;
        if (!code) code = emp.employeeType;  // 兜底用原值
    }
    var cls = EMPLOYEE_TYPE_BADGE[code] || 'bg-light text-dark border';
    var name = null;
    if (emp.employeeTypeId != null) {
        var t = (typeof EMPLOYEE_TYPES !== 'undefined') ? EMPLOYEE_TYPES.find(function(x){return x.id === emp.employeeTypeId;}) : null;
        if (t) name = t.name;
    }
    if (!name) name = emp.employeeTypeName || emp.employeeType || '-';
    return '<span class="badge ' + cls + '" title="FK: EmployeeType.Id = ' + (emp.employeeTypeId || '-') + '">' + name + '</span>';
}

// 员工类型中文名解析助手（人员 → Name 字符串）
function employeeTypeName(emp) {
    if (!emp) return '-';
    if (emp.employeeTypeId != null) {
        var t = (typeof EMPLOYEE_TYPES !== 'undefined') ? EMPLOYEE_TYPES.find(function(x){return x.id === emp.employeeTypeId;}) : null;
        if (t) return t.name;
    }
    return emp.employeeTypeName || emp.employeeType || '-';
}


// =====================================================================
// v2.12.6 BOOKINGS 关联函数：人员清单的"住宿状态"和"宿舍房号"
// 业务规则：
//   - 人员的"住宿状态"取自 BOOKINGS 表中该人员的最后一次有效操作记录
//   - 人员的"宿舍房号"取自 BOOKINGS 表中该人员最后一次有效操作的 dormCode
//   - 入住登记（type=1, status=2）→ 已住宿（LODGED），dormCode 更新为新房号
//   - 退房登记（type=2, status=3）→ 未住宿（NOT_LODGED），dormCode 清空
//   - 预约（type=1, status=1）→ 不算"已住宿"，dormCode 也未生效
//   - 取消（status=4）→ 该记录作废，不影响状态
//   - 选项值关联引用基础资料 ResidenceStatus 字典（参见 §13.5 v2.12.6 字典映射表）
// =====================================================================

// ⚠️ v2.11.30 移除：getLatestValidBooking / getResidenceStatusCode / getResidenceStatusByCode
//   原因：已提前到 normalizeData IIFE 之前定义（避免 IIFE 内同步逻辑被跳过）

// 获取员工的"宿舍房号"（基于 BOOKINGS 最后有效记录）

// 获取员工的"宿舍房号"（基于 BOOKINGS 最后有效记录）
// 入住 → dormCode
// 退房 → null（清空）
// 无记录 → null
function getLatestDormCode(p) {
    if (!p) return null;
    var b = getLatestValidBooking(p.id);
    if (!b) return null;
    if (b.type === 1 && b.status === 2) return b.dormCode || null;
    if (b.type === 2 && b.status === 3) return null; // 退房后清空
    return null;
}

// 获取所有出现过的 dormCode 列表（用于筛选下拉）
function getAllDormCodes() {
    var codes = [];
    var seen = {};
    if (typeof BOOKINGS !== 'undefined') {
        for (var i = 0; i < BOOKINGS.length; i++) {
            var c = BOOKINGS[i].dormCode;
            if (c && !seen[c]) { seen[c] = true; codes.push(c); }
        }
    }
    if (typeof DORMS !== 'undefined') {
        for (var j = 0; j < DORMS.length; j++) {
            var dc = DORMS[j].dormCode;
            if (dc && !seen[dc]) { seen[dc] = true; codes.push(dc); }
        }
    }
    codes.sort();
    return codes;
}

